<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Kanban Board</title>
<style>
  :root {
    --bg: #f4f5f7;
    --col-bg: #ebecf0;
    --card-bg: #ffffff;
    --text: #172b4d;
    --muted: #5e6c84;
    --accent: #0079bf;
    --shadow: 0 1px 2px rgba(9,30,66,0.25);
    --shadow-lg: 0 4px 12px rgba(9,30,66,0.35);
  }

  * { box-sizing: border-box; }

  body {
    margin: 0;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    background: var(--bg);
    color: var(--text);
    min-height: 100vh;
  }

  header.app-header {
    padding: 20px 24px;
    background: var(--accent);
    color: #fff;
  }

  header.app-header h1 {
    margin: 0;
    font-size: 20px;
    font-weight: 600;
    letter-spacing: 0.3px;
  }

  .add-bar {
    display: flex;
    gap: 8px;
    padding: 16px 24px;
    background: var(--bg);
    position: sticky;
    top: 0;
    z-index: 5;
  }

  #new-card {
    flex: 1;
    max-width: 420px;
    padding: 10px 12px;
    border: 1px solid #dfe1e6;
    border-radius: 6px;
    font-size: 14px;
    outline: none;
    background: #fff;
  }

  #new-card:focus {
    border-color: var(--accent);
    box-shadow: 0 0 0 2px rgba(0,121,191,0.2);
  }

  #add-card {
    padding: 10px 18px;
    border: none;
    border-radius: 6px;
    background: var(--accent);
    color: #fff;
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.15s;
  }

  #add-card:hover { background: #026aa7; }
  #add-card:active { transform: translateY(1px); }

  .board {
    display: flex;
    gap: 16px;
    padding: 8px 24px 32px;
    align-items: flex-start;
    overflow-x: auto;
  }

  .column {
    background: var(--col-bg);
    border-radius: 10px;
    width: 300px;
    min-width: 300px;
    display: flex;
    flex-direction: column;
    max-height: calc(100vh - 160px);
  }

  .column-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 14px 16px 10px;
    font-weight: 600;
    font-size: 14px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: var(--muted);
  }

  .count {
    background: rgba(9,30,66,0.13);
    color: var(--muted);
    border-radius: 12px;
    padding: 2px 9px;
    font-size: 12px;
    font-weight: 700;
    min-width: 22px;
    text-align: center;
  }

  .cards {
    flex: 1;
    padding: 4px 12px 12px;
    overflow-y: auto;
    min-height: 60px;
    transition: background 0.15s;
  }

  .column.drag-over .cards {
    background: rgba(0,121,191,0.08);
  }

  .card {
    background: var(--card-bg);
    border-radius: 8px;
    box-shadow: var(--shadow);
    padding: 12px 12px 12px 14px;
    margin-bottom: 10px;
    cursor: grab;
    display: flex;
    align-items: flex-start;
    gap: 8px;
    position: relative;
    border-left: 3px solid var(--accent);
    word-break: break-word;
  }

  .card:hover { box-shadow: var(--shadow-lg); }
  .card.dragging { opacity: 0.5; }

  .card-title {
    flex: 1;
    font-size: 14px;
    line-height: 1.4;
    white-space: pre-wrap;
  }

  .card-del {
    border: none;
    background: transparent;
    color: var(--muted);
    cursor: pointer;
    font-size: 16px;
    line-height: 1;
    padding: 2px 4px;
    border-radius: 4px;
    flex-shrink: 0;
    opacity: 0.5;
    transition: opacity 0.15s, background 0.15s, color 0.15s;
  }

  .card:hover .card-del { opacity: 1; }
  .card-del:hover { background: #ffebe6; color: #de350b; }

  .empty-hint {
    color: var(--muted);
    font-size: 13px;
    text-align: center;
    padding: 16px 8px;
    opacity: 0.6;
    font-style: italic;
  }
</style>
</head>
<body>
  <header class="app-header">
    <h1>Kanban Board</h1>
  </header>

  <div class="add-bar">
    <input id="new-card" type="text" placeholder="Enter a card title…" autocomplete="off">
    <button id="add-card">Add Card</button>
  </div>

  <main class="board">
    <section class="column" id="col-todo" data-col="todo">
      <div class="column-header">
        <span>To Do</span>
        <span class="count">0</span>
      </div>
      <div class="cards"></div>
    </section>

    <section class="column" id="col-doing" data-col="doing">
      <div class="column-header">
        <span>Doing</span>
        <span class="count">0</span>
      </div>
      <div class="cards"></div>
    </section>

    <section class="column" id="col-done" data-col="done">
      <div class="column-header">
        <span>Done</span>
        <span class="count">0</span>
      </div>
      <div class="cards"></div>
    </section>
  </main>

<script>
(function () {
  "use strict";

  var STORAGE_KEY = "kanban.board.v1";
  var COLUMNS = ["todo", "doing", "done"];

  // state: array of { id, title, col }
  var state = load();
  var idCounter = 0;

  function load() {
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      if (!raw) return [];
      var parsed = JSON.parse(raw);
      if (!Array.isArray(parsed)) return [];
      return parsed.filter(function (c) {
        return c && typeof c.id === "string" &&
               typeof c.title === "string" &&
               COLUMNS.indexOf(c.col) !== -1;
      });
    } catch (e) {
      return [];
    }
  }

  function save() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
    } catch (e) { /* ignore quota errors */ }
  }

  function newId() {
    idCounter += 1;
    return "card-" + Date.now().toString(36) + "-" + idCounter;
  }

  function colContainer(col) {
    return document.querySelector("#col-" + col + " .cards");
  }

  function countEl(col) {
    return document.querySelector("#col-" + col + " .count");
  }

  function buildCard(card) {
    var el = document.createElement("div");
    el.className = "card";
    el.setAttribute("draggable", "true");
    el.dataset.id = card.id;

    var title = document.createElement("span");
    title.className = "card-title";
    title.textContent = card.title;

    var del = document.createElement("button");
    del.className = "card-del";
    del.type = "button";
    del.setAttribute("aria-label", "Delete card");
    del.textContent = "\u00D7";

    el.appendChild(title);
    el.appendChild(del);
    return el;
  }

  function render() {
    COLUMNS.forEach(function (col) {
      var container = colContainer(col);
      container.innerHTML = "";
      var cards = state.filter(function (c) { return c.col === col; });
      cards.forEach(function (card) {
        container.appendChild(buildCard(card));
      });
      if (cards.length === 0) {
        var hint = document.createElement("div");
        hint.className = "empty-hint";
        hint.textContent = "No cards";
        container.appendChild(hint);
      }
      countEl(col).textContent = String(cards.length);
    });
  }

  function addCard(title) {
    title = title.trim();
    if (!title) return;
    state.push({ id: newId(), title: title, col: "todo" });
    save();
    render();
  }

  function deleteCard(id) {
    state = state.filter(function (c) { return c.id !== id; });
    save();
    render();
  }

  function moveCard(id, col) {
    if (COLUMNS.indexOf(col) === -1) return;
    var card = null;
    for (var i = 0; i < state.length; i++) {
      if (state[i].id === id) { card = state[i]; break; }
    }
    if (!card || card.col === col) return;
    card.col = col;
    save();
    render();
  }

  // --- Event wiring ---

  var input = document.getElementById("new-card");
  var addBtn = document.getElementById("add-card");

  addBtn.addEventListener("click", function () {
    addCard(input.value);
    input.value = "";
    input.focus();
  });

  input.addEventListener("keydown", function (e) {
    if (e.key === "Enter") {
      addCard(input.value);
      input.value = "";
    }
  });

  // Delete via delegation on the board
  document.querySelector(".board").addEventListener("click", function (e) {
    var btn = e.target.closest(".card-del");
    if (!btn) return;
    var cardEl = btn.closest(".card");
    if (cardEl) deleteCard(cardEl.dataset.id);
  });

  // Drag and drop
  var draggingId = null;

  document.querySelector(".board").addEventListener("dragstart", function (e) {
    var cardEl = e.target.closest(".card");
    if (!cardEl) return;
    draggingId = cardEl.dataset.id;
    cardEl.classList.add("dragging");
    if (e.dataTransfer) {
      e.dataTransfer.effectAllowed = "move";
      e.dataTransfer.setData("text/plain", draggingId);
    }
  });

  document.querySelector(".board").addEventListener("dragend", function (e) {
    var cardEl = e.target.closest(".card");
    if (cardEl) cardEl.classList.remove("dragging");
    draggingId = null;
    COLUMNS.forEach(function (col) {
      document.getElementById("col-" + col).classList.remove("drag-over");
    });
  });

  COLUMNS.forEach(function (col) {
    var column = document.getElementById("col-" + col);

    column.addEventListener("dragover", function (e) {
      e.preventDefault();
      if (e.dataTransfer) e.dataTransfer.dropEffect = "move";
      column.classList.add("drag-over");
    });

    column.addEventListener("dragleave", function (e) {
      if (!column.contains(e.relatedTarget)) {
        column.classList.remove("drag-over");
      }
    });

    column.addEventListener("drop", function (e) {
      e.preventDefault();
      column.classList.remove("drag-over");
      var id = draggingId;
      if (!id && e.dataTransfer) id = e.dataTransfer.getData("text/plain");
      if (id) moveCard(id, col);
    });
  });

  render();
})();
</script>
</body>
</html>
